<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {NotebookPen,Download} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document,LocalStory} from '../domain/local-contract'
import type {LocalNote} from '../reader/local-tools'
import Sheet from '../components/Sheet.vue'
const store=useLocal(),route=useRoute(),notes=ref<Document<LocalNote>[]>([]),stories=ref<Document<LocalStory>[]>([]),query=ref(''),group=ref(''),error=ref(''),busy=ref(true),edit=ref<Document<LocalNote>|null>(null),text=ref(''),editGroup=ref(''),saving=ref(false)
const groups=computed(()=>[...new Set(notes.value.filter(row=>!row.value.retired).map(row=>row.value.group||'未分组'))])
const shown=computed(()=>notes.value.filter(row=>!row.value.retired&&(!route.query.story||row.value.anchor.storyId===route.query.story)&&(!group.value||(row.value.group||'未分组')===group.value)&&(!query.value||(row.value.text+'\n'+(row.value.quote||'')).includes(query.value))))
const title=(id:string)=>stories.value.find(story=>story.id===id)?.value.title||'来源不可用'
const link=(note:LocalNote)=>({path:'/local/read/'+note.anchor.storyId,query:{branch:note.anchor.branchId||undefined,paragraph:note.anchor.paragraphId,offset:String(note.anchor.offset),revision:note.anchor.lineRevision?String(note.anchor.lineRevision):undefined}})
async function load(){const vault=store.vault;if(!vault)return;try{[notes.value,stories.value]=await Promise.all([vault.list<LocalNote>('note'),vault.list<LocalStory>('story')]);notes.value.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function open(row:Document<LocalNote>){edit.value=row;text.value=row.value.text;editGroup.value=row.value.group||'';error.value=''}
async function save(){const vault=store.vault,row=edit.value;if(!vault||!row||saving.value)return;saving.value=true;const value={...row.value,text:text.value,group:editGroup.value.trim()};try{await vault.commit(crypto.randomUUID(),'note',row.id,row.revision,value);edit.value=null;await load()}catch(e){if((e as {code?:string}).code==='REVISION_CONFLICT'){try{await vault.commit(crypto.randomUUID(),'note',crypto.randomUUID(),0,{...value,conflictOf:row.id});edit.value=null;await load();error.value='其他窗口已有修改，你的内容已另存一份。'}catch(failure){error.value=(failure as Error).message}}else error.value=(e as Error).message}finally{saving.value=false}}
async function retire(row:Document<LocalNote>){if(!store.vault)return;try{await store.vault.commit(crypto.randomUUID(),'note',row.id,row.revision,{...row.value,retired:true});await load()}catch(e){error.value=(e as Error).message}}
function exportNotes(){const data=JSON.stringify({format:'reader-notes-v1',exportedAt:new Date().toISOString(),notes:shown.value.map(row=>({id:row.id,revision:row.revision,story:title(row.value.anchor.storyId),...row.value}))},null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='阅读笔记.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>void load())
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">MARGINALIA</span><h1>阅读笔记</h1></div><button :disabled="!shown.length" @click="exportNotes"><Download :size="18"/>导出</button></div><p v-if="error" class="final-error" role="alert">{{error}}</p><div class="final-note-filters"><label>搜索<input v-model="query" type="search" placeholder="笔记或摘录"></label><label>分组<select v-model="group"><option value="">全部</option><option v-for="name in groups" :key="name">{{name}}</option></select></label></div><p v-if="busy" role="status">正在打开笔记…</p><div v-else-if="!shown.length" class="final-empty"><NotebookPen :size="32"/><h2>页边的留白</h2><p class="final-subtle">阅读时选中一段文字，写下你的想法。</p></div><div v-else class="final-notes-grid"><article v-for="row in shown" :key="row.id" class="final-setting-card"><RouterLink class="final-text-link" :to="link(row.value)">{{title(row.value.anchor.storyId)}}</RouterLink><blockquote v-if="row.value.quote">{{row.value.quote}}</blockquote><p class="final-note-text">{{row.value.text||'书签'}}</p><small class="final-subtle">{{row.value.group||'未分组'}}<span v-if="row.value.conflictOf"> · 保留的冲突副本</span></small><div class="final-page-actions"><button @click="open(row)">编辑</button><button @click="retire(row)">归档</button></div></article></div><Sheet v-if="edit" title="编辑笔记" @close="!saving&&(edit=null)"><form class="final-note-editor" @submit.prevent="save"><blockquote v-if="edit.value.quote">{{edit.value.quote}}</blockquote><label>想法<textarea v-model="text" maxlength="1000000" rows="6"/></label><label>分组<input v-model="editGroup" maxlength="120"></label><p v-if="error" class="final-error" role="alert">{{error}}</p><button class="primary" :disabled="saving">保存</button></form></Sheet></section></template>
